/**
 * formatos-scfi.js — Formatos imprimibles (PDF) de una verificación SCFI.
 *   · Solicitud de servicio  FT-01-01-2
 *   · Dictamen de inspección FT-01-03 rev 3
 * Se abre en una pestaña nueva lista para "Guardar como PDF" (Ctrl+P).
 * Lee: sudi_v_scfi_insp_lista, sudi_scfi_inspecciones, estaciones_servicio, clientes_catalogo,
 *      sudi_scfi_instrumentos, sudi_scfi_hologramas, sudi_usuarios, sudi_scfi_equipos (instrumentos patrón).
 * Uso: SUDIFormatos.abrir('solicitud' | 'dictamen', inspeccionId)
 */
(() => {
    'use strict';
    const LOGO = {
        JOMAR: 'data:image/png;base64,',
        EMA: 'data:image/png;base64,',
        UVIM: 'data:image/png;base64,',
    };
    const UI = 'JOMAR VERIFICACIONES, S. DE R.L. DE C.V.';
    const ACRED = 'UVIM 131';
    const TEL_UI = '614-438-47-81';
    const TEL_PIE = '0446142356507';
    const MAIL_UI = 'info@jomarverifica.com.mx';
    const ALFA = 0.0000477;
    const MES = ['Ene', 'Feb', 'Mar', 'Abr', 'May', 'Jun', 'Jul', 'Ago', 'Sep', 'Oct', 'Nov', 'Dic'];
    const TIPOS = {
        periodica_1: 'Periódica', periodica_2: 'Periódica', extraordinaria_1: 'Extraordinaria', extraordinaria_2: 'Extraordinaria', inicial: 'Inicial',
    };

    const esc = (t) => String(t ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]));
    const v = (t, def = '') => (t === null || t === undefined || t === '' ? def : esc(t));
    const fecha = (f) => { if (!f) return ''; const [a, m, d] = String(f).slice(0, 10).split('-'); return `${Number(d)} ${MES[Number(m) - 1]} ${a}`; };
    const hhmm = (t) => (t ? String(t).slice(0, 5) : '');
    const hora12 = (t) => { if (!t) return ''; let [h, m] = String(t).split(':').map(Number); const s = h >= 12 ? 'pm' : 'am'; h = h % 12 || 12; return `${h}:${String(m).padStart(2, '0')} ${s}`; };
    const money = (n) => Number(n || 0).toLocaleString('es-MX', { minimumFractionDigits: 2, maximumFractionDigits: 2 });

    // ---------------------------------------------------------------
    // Datos
    // ---------------------------------------------------------------
    async function datos(DB, id) {
        const sb = DB.sb;
        const uno = async (q) => { const { data, error } = await q; if (error) throw new Error(DB.mensajeError ? DB.mensajeError(error) : error.message); return data; };
        const vista = await uno(sb.from('sudi_v_scfi_insp_lista').select('*').eq('id', id).single());
        const tabla = await uno(sb.from('sudi_scfi_inspecciones').select('*').eq('id', id).single());
        const i = { ...vista, ...tabla };
        const [est, cli, inst, holos, usuarios, equipos] = await Promise.all([
            i.estacion_id ? uno(sb.from('estaciones_servicio').select('*').eq('id', i.estacion_id).maybeSingle()) : null,
            i.cliente_id ? uno(sb.from('clientes_catalogo').select('*').eq('id', i.cliente_id).maybeSingle()) : null,
            uno(sb.from('sudi_scfi_instrumentos').select('*').eq('inspeccion_id', id).order('orden')),
            uno(sb.from('sudi_scfi_hologramas').select('id, tipo, folio').eq('inspeccion_id', id)),
            uno(sb.from('sudi_usuarios').select('*').in('id', [i.inspector_id, i.realizo_id].filter(Boolean).length ? [i.inspector_id, i.realizo_id].filter(Boolean) : ['00000000-0000-0000-0000-000000000000'])),
            uno(sb.from('sudi_scfi_equipos').select('*').eq('activo', true)),
        ]);
        // Dispensarios de la estación (aprobación DGN y gastos mín/máx) para la inspección visual
        const disps = i.estacion_id ? await sb.from('sudi_estacion_dispensarios').select('*').eq('estacion_id', i.estacion_id).eq('activo', true).then((r) => r.data || []) : [];
        const normS = (t) => String(t ?? '').toUpperCase().replace(/\s+/g, '');
        const dispDe = (x) => disps.find((dd) => normS(dd.serie) && normS(dd.serie) === normS(x.serie)) || null;
        const aprob = (dd) => { if (!dd?.numero_aprobacion) return ''; const n = String(dd.numero_aprobacion); return dd.anio_aprobacion && !n.includes(String(dd.anio_aprobacion)) ? `${n}/${dd.anio_aprobacion}` : n; };
        const porId = Object.fromEntries((holos || []).map((h) => [h.id, h]));
        const fmtF = (tipo, f) => (f === null || f === undefined || f === '' ? '' : (window.SUDIHolo ? SUDIHolo.fmtFolio(tipo, f) : String(f)));
        const flexTipo = i.tipo === 'inicial' ? 'inicial' : 'flexograma';
        const lados = (inst || []).map((x) => ({
            ...x,
            aprobacion_dgn: aprob(dispDe(x)), gasto_min: dispDe(x)?.gasto_min ?? null, gasto_max: dispDe(x)?.gasto_max ?? null,
            flexograma: fmtF(flexTipo, porId[x.holograma_id]?.folio),
            distintivo: fmtF('distintivo', porId[x.distintivo_id]?.folio),
            precinto: fmtF('precinto', porId[x.precinto_id]?.folio),
        }));
        const us = Object.fromEntries((usuarios || []).map((u) => [u.id, u]));
        const inspector = us[i.inspector_id] || us[i.realizo_id] || null;
        // Equipo patrón: el del verificador que realizó el trabajo; si no tiene, el del verificador que firma.
        const equipo = (equipos || []).find((e) => e.verificador_id === i.realizo_id) || (equipos || []).find((e) => e.verificador_id === i.inspector_id) || null;
        return { i, est: est || {}, cli: cli || {}, lados, inspector, equipo };
    }

    function domicilio(est) {
        const cp = est.codigo_postal ? `C.P ${est.codigo_postal}` : '';
        return [est.direccion, est.colonia, cp].filter(Boolean).join(', ');
    }
    const lugar = (est) => [est.municipio, est.estado].filter(Boolean).join(', ');
    const nombreInspector = (d) => d.inspector?.nombre_completo || d.i.inspector || d.i.realizo || '';
    const visitado = (d) => d.est.encargado || d.cli.representante || '';
    const permiso = (d) => d.i.permiso || d.est.permiso || '';
    const noEstacion = (d) => d.i.numero_estacion || d.est.numero_estacion || '';

    // ---------------------------------------------------------------
    // Estilos comunes
    // ---------------------------------------------------------------
    const CSS = `
        @page { size: letter; margin: 10mm 12mm; }
        * { box-sizing: border-box; }
        body { font-family: 'DejaVu Serif', Georgia, 'Times New Roman', serif; color: #111; margin: 0; font-size: 10.5px; }
        .page { width: 100%; min-height: 252mm; position: relative; padding-bottom: 18mm; page-break-after: always; }
        .page:last-child { page-break-after: auto; }
        .page.sol { min-height: 0; padding-bottom: 0; }
        table { border-collapse: collapse; width: 100%; }
        td, th { padding: 2px 4px; vertical-align: middle; }
        .b td, .b th { border: 1px solid #222; }
        .gold td { border: 1px solid #c9a227; color: #555; font-size: 9.5px; }
        .c { text-align: center; } .r { text-align: right; } .bold { font-weight: bold; }
        .gris { color: #777; } .rojo { color: #d00; }
        .logos { display: flex; align-items: center; justify-content: space-between; margin: 10px 4px; }
        .logos img { height: 52px; }
        .pie { position: absolute; bottom: 0; left: 0; right: 0; font-size: 8.5px; color: #888; display: flex; justify-content: space-between; gap: 20px; }
        .pie .azul { color: #2a6fdb; }
        .thg th { background: #bdbdbd; font-weight: normal; font-size: 8.5px; border: 1px solid #999; }
        .tdg td { font-size: 9px; text-align: center; border-bottom: 1px solid #eee; }
        .met { margin-bottom: 8px; page-break-inside: avoid; }
        .met td, .met th { border: 1px solid #555; font-size: 7.6px; text-align: center; padding: 1px 2px; }
        .met .hd { text-align: left; font-size: 8.5px; border: none; padding: 2px 0; }
        .vac { color: #bbb; }
        .firma { border-top: 1px solid #222; padding-top: 3px; text-align: center; font-size: 9px; }
        .aviso { background: #fff7d6; border: 1px solid #e5c100; padding: 6px 10px; margin-bottom: 8px; font-family: sans-serif; font-size: 11px; }
        @media print { .no-print { display: none !important; } }
        body.exportando { background: #fff; }
        body.exportando .no-print { display: none !important; }
        body.exportando .hoja { padding: 0; max-width: 216mm; }
        body.exportando .page { box-shadow: none; margin: 0; padding: 8mm 10mm 0; height: 277mm; min-height: 0; overflow: hidden; }
        body.exportando .page .pie { left: 10mm; right: 10mm; bottom: 8mm; }
        .barra { position: sticky; top: 0; background: #0F111A; color: #fff; padding: 10px 14px; font-family: sans-serif; display: flex; gap: 10px; align-items: center; justify-content: space-between; z-index: 5; }
        .barra button { margin-left: 6px; background: #EAB308; border: 0; padding: 8px 16px; border-radius: 8px; font-weight: 700; cursor: pointer; }
        .hoja { max-width: 216mm; margin: 0 auto; background: #fff; padding: 6mm; }
        @media screen { body { background: #e5e7eb; } .page { background: #fff; margin-bottom: 8mm; padding: 8mm 10mm 22mm; box-shadow: 0 2px 8px rgba(0,0,0,.15); } .page .pie { left: 10mm; right: 10mm; bottom: 6mm; } }
    `;

    function documento(titulo, cuerpo, avisos = [], archivo = 'documento') {
        return `<!DOCTYPE html><html lang="es"><head><meta charset="UTF-8"><title>${esc(titulo)}</title><style>${CSS}</style></head><body>
            <div class="barra no-print"><span>${esc(titulo)}</span><span><button id="btn-pdf" onclick="descargarPDF()">Descargar PDF</button><button onclick="window.print()" style="background:#32384e;color:#fff">Imprimir</button></span></div>
            <div class="hoja">${avisos.length ? `<div class="aviso no-print"><b>Revisa antes de imprimir:</b><br>${avisos.map(esc).join('<br>')}</div>` : ''}${cuerpo}</div>
            <script src="https://cdnjs.cloudflare.com/ajax/libs/html2pdf.js/0.10.1/html2pdf.bundle.min.js"></script>
            <script>
                function descargarPDF() {
                    var b = document.getElementById('btn-pdf');
                    if (!window.html2pdf) { alert('No cargó el generador de PDF (revisa tu conexión). Usa Imprimir → Guardar como PDF.'); return; }
                    b.disabled = true; b.textContent = 'Generando...';
                    document.body.classList.add('exportando');
                    window.scrollTo(0, 0);
                    html2pdf().set({
                        margin: 0, filename: ${JSON.stringify(archivo + '.pdf')},
                        image: { type: 'jpeg', quality: 0.95 },
                        html2canvas: { scale: 2, useCORS: true, scrollY: 0 },
                        jsPDF: { unit: 'mm', format: 'letter', orientation: 'portrait' },
                        pagebreak: { mode: ['css'] },
                    }).from(document.querySelector('.hoja')).save()
                        .catch(function (e) { alert('No se pudo generar el PDF: ' + e.message); })
                        .then(function () { document.body.classList.remove('exportando'); b.disabled = false; b.textContent = 'Descargar PDF'; });
                }
            </script>
        </body></html>`;
    }
    const logos = () => `<div class="logos"><img src="${LOGO.JOMAR}" alt="JOMAR"><img src="${LOGO.EMA}" alt="ema"><img src="${LOGO.UVIM}" alt="UVIM" style="height:60px"></div>`;

    // ---------------------------------------------------------------
    // Solicitud de servicio FT-01-01-2
    // ---------------------------------------------------------------
    function solicitud(d) {
        const { i, est, cli, lados } = d;
        const grupos = {};
        lados.forEach((l) => { const k = `${l.marca || ''}|${l.modelo || ''}|${l.serie || ''}`; (grupos[k] = grupos[k] || { marca: l.marca, modelo: l.modelo, serie: l.serie, n: 0 }).n++; });
        const filas = Object.values(grupos);
        const total = lados.length || Number(i.mangueras_calc ?? i.mangueras ?? 0) || 0;
        const precio = total * Number(i.precio_por_manguera || 0);
        const avisos = [];
        if (!lados.length) avisos.push('La verificación no tiene lados capturados: la tabla de instrumentos sale vacía.');
        if (!visitado(d)) avisos.push('La estación no tiene encargado capturado (Nombre del solicitante).');
        if (!cli.rfc) avisos.push('El cliente no tiene RFC capturado.');
        if (!i.precio_por_manguera) avisos.push('No hay costo por instrumento capturado.');
        const cuerpo = `<div class="page sol">
            ${logos()}
            <p class="c" style="margin:0">Acreditación y Aprobación No. ${ACRED}</p>
            <table style="margin-bottom:2px"><tr><td style="width:33%"></td><td class="c" style="font-size:13px">SOLICITUD DE SERVICIO</td><td class="r rojo" style="font-size:13px">Folio No: ${v(i.folio)}</td></tr></table>
            <table class="b">
                <tr><td style="width:18%">RAZON SOCIAL:</td><td colspan="5">${v(cli.razon_social || i.razon_social)}</td></tr>
                <tr><td>NOMBRE DEL SOLICITANTE:</td><td colspan="5">${v(visitado(d))}</td></tr>
                <tr><td>DOMICILIO:</td><td colspan="5">${v(domicilio(est))}${lugar(est) ? `,<br>${v(lugar(est))}.` : ''}</td></tr>
                <tr><td>RFC:</td><td colspan="5">${v(cli.rfc)}</td></tr>
                <tr><td>TEL:</td><td style="width:13%">${v(cli.telefono)}</td><td style="width:12%">No. DE PL:</td><td style="width:20%">${v(permiso(d))}</td><td style="width:11%">E-MAIL:</td><td>${v(cli.correo || i.cliente_correo)}</td></tr>
            </table>
            <table class="b" style="margin-top:6px">
                <tr><td style="width:18%">Tipo de Inspección:</td><td>${v(TIPOS[i.tipo] || i.tipo)}</td></tr>
                <tr><td colspan="2">Inspección conforme a lo establecido en la NOM-005-SCFI-2017, Instrumentos de medición-Sistema para medición y despacho de gasolina y otros combustibles líquidos con un gasto máximo de 250 L/min-Especificaciones, métodos de prueba y de inspección que realice JOMAR conforme al punto 9.</td></tr>
            </table>
            <p class="c bold" style="margin:6px 0 2px">Por medio del presente, solicito la inspección de los siguientes instrumentos de medición:</p>
            <table class="b"><tr class="bold c"><td style="width:20%">Cantidad de Instrumentos</td><td>Marca</td><td>Modelo</td><td>Serie</td></tr></table>
            <table>${filas.map((f) => `<tr class="c" style="border-bottom:1px solid #d00"><td style="width:20%">${f.n}</td><td>${v(f.marca)}</td><td>${v(f.modelo)}</td><td>${v(f.serie)}</td></tr>`).join('') || '<tr><td class="c vac" colspan="4">Sin instrumentos</td></tr>'}</table>
            <table style="margin-top:2px"><tr><td>Total de Instrumentos: ${total}</td><td class="r" style="width:30%">Precio del Servicio:<br>(IVA Incluido)</td><td style="width:14%">$${money(precio)}</td></tr></table>
            <div style="font-size:9px;line-height:1.2;margin-top:6px">
                El servicio se realizara de acuerdo a lo siguiente:<br>
                • La fecha de inspección será programada por la Unidad de Inspección y el cliente.<br>
                • El cliente tiene la obligación de permitirle el acceso a los instrumentos de medición al Inspector a fin de llevar a cabo la inspección.<br>
                • La Unidad de Inspección emitirá un Dictamen de inspección, colocará flexogramas y distintivos conforme a lo establecido en la LISTA de instrumentos de medición cuya inspección inicial, periódica o extraordinaria es obligatoria, así como las Dispensarios aplicables para efectuarla.<br>
                • La Unidad de Inspección guardára absoluta confidencialidad de toda la información generada por los servicios de inspección. Si usted quiere conocer nuestra política de CONFIDENCIALIDAD puede solicitarla al mail de la unidad de inspección.<br>
                • La información relativa a los servicios de inspección es susceptible de compartir con autoridades que regulan a las Unidades de Inspección.<br>
                • La información que se hará publica es la que a solicitud de la PROCURADURIA FEDERAL DEL CONSUMIDOR, DIRECCION GENERAL DE Dispensarios DE LA SECRETARIA DE ECONOMIA Y LA ENTIDAD MEXICANA DE ACREDITACION solicite en base a la LISTA de instrumentos de medición cuya Inspección inicial, periódica o extraordinaria es obligatoria, así como las Dispensarios aplicables para efectuarla.<br>
                • Si se requiere alguna corrección o adición a este documento o sus complementos después de concluido y/o entregado, el usuario deberá ponerse en contacto con la Unidad de Inspección para su modificación.<br>
                • Este documento si no cuenta con el nombre y firma del inspector acreditado y aprobado no tendrá validez.<br>
                • La Unidad de Inspección cuenta con un seguro que cubre la responsabilidad civil en que pueda incurrir por los servicios de Inspección.<br>
                • La Unidad de Inspección y todo su personal bajo ningún motivo podrá recibir ningún tipo de gratificación o incentivo así como realizar servicios de reparación, mantenimiento ó venta de los elementos que se inspeccionan.<br>
                • El cliente se obliga a pagar a ${UI} por los servicios de inspección realizados.<br>
                • El Recurso de quejas, reclamaciones y apelaciones, se atenderá conforme a lo establecido en el artículo 163° de la Ley de la Infraestructura de la Calidad. La unidad de inspección cuenta con un procedimiento para la atención de quejas que será proporcionado en copia simple en el momento que lo solicite el cliente.<br>
                • El cliente se da por enterado de que la condición de instrumento inpseccionado se pierde cuando:<br>
                a) Se destruya, remueva, viole o altere de cualquier forma el dispositivo de inviolabilidad, aun cuando esto hubiere ocurrido por caso fortuito o por reparación del instrumento de medición.<br>
                b) Se alteren por cualquier medio los mecanismos de funcionamiento y uso del instrumento de medición en detrimento de sus características metrológicas y condiciones de funcionamiento asignadas.<br>
                c) Para el caso de taxímetros; se instale en un vehículo diferente a aquél en el que se inspecciono. NO APLICA<br>
                d) El instrumento se haya ajustado o reparado, sin dar aviso.<br>
                e) Cuando el holograma y/o precinto no haya sido colocado en el instrumento de medición o donde lo establezca la(s) norma(s) correspondiente(s).<br>
                f) Cuando el usuario o el suministrador del servicio no cuente con el Dictamen de inspección que avala que el instrumento de medición ha sido inspeccionado.<br>
                g) Cuando el holograma y/o precinto sea removido del instrumento de forma intencional o de manera fortuita, o éste se encuentre destruido o sea falso.<br>
                Cuando se pierda la validez de la inspección, el usuario o suministrador del servicio o quien lo utilice, deberá solicitar una inspección extraordinaria.<br>
                • El cliente al firmar de aceptado entiende y acepta todas y cada una de las condiciones establecidas en el presente documento
            </div>
            <p style="margin:12px 0 2px">${UI} , Tel ${TEL_UI}</p>
            <table class="b">
                <tr class="c"><td colspan="2">Solicitante</td><td colspan="2">Unidad de Inspección</td></tr>
                <tr><td style="width:10%;border-right:0">Nombre:</td><td style="border-left:0">${v(visitado(d))}</td><td style="width:10%;border-right:0">Nombre:</td><td style="border-left:0">${v(nombreInspector(d))}</td></tr>
                <tr><td style="border-right:0">Fecha:</td><td style="border-left:0">${fecha(i.fecha_inspeccion)}</td><td style="border-right:0">Fecha:</td><td style="border-left:0">${fecha(i.fecha_inspeccion)}</td></tr>
            </table>
            <p style="margin:2px 0">FT-01-01-2</p>
        </div>`;
        return documento(`Solicitud ${i.folio}`, cuerpo, avisos, `Solicitud_numero_${i.folio}`);
    }

    // ---------------------------------------------------------------
    // Dictamen de inspección FT-01-03 rev 3
    // ---------------------------------------------------------------
    function encabezado(d, n, total) {
        const { i } = d;
        return `<table style="margin-bottom:4px"><tr><td class="gris" style="width:33%;font-size:10px">Folio No.: ${v(i.folio)}</td><td class="c bold" style="font-size:17px">DICTAMEN DE INSPECCIÓN</td><td class="r gris" style="width:33%;font-size:10px">FT-01-03 rev 3</td></tr></table>
            <table class="gold"><tr>
                <td style="width:26%">Los resultados de la inspección se relacionan exclusivamente con la solicitud del servicio y el Dictamen Folio:</td>
                <td>${v(i.folio)}</td><td>Fecha:</td><td>${fecha(i.fecha_inspeccion)}</td><td>Hoja:</td><td>${n}/${total}</td><td>No. Estación</td><td>${v(noEstacion(d))}</td><td>${v(permiso(d))}</td>
            </tr></table>`;
    }
    const pieDict = () => `<div class="pie"><div>FT-01-03-3<br><br><span class="azul">Teléfono: ${TEL_PIE}</span></div><div style="max-width:55%">El presente documento no se reproducirá sin omitir nada, sin la aprobación de la unidad de Inspección y el Cliente.<br><br><span class="azul" style="float:right">${MAIL_UI}</span></div></div>`;

    function instPatron(eq, clave) { return eq?.instrumentos?.[clave] || null; }

    // Bloque de pruebas metrológicas por lado. Usa x.pruebas si existe; si no, celdas en blanco.
    function bloqueMetrologico(d, l) {
        const vol = instPatron(d.equipo, 'volumetrico');
        const mv = vol ? (vol.id_interna || vol.serie || '') : '';
        const p = l.pruebas || {};
        const G = [['max', 'Gasto Máximo'], ['med', 'Gasto Medio'], ['min', 'Gasto Mínimo']];
        const celdas = (arr, n) => Array.from({ length: n }, (_, k) => `<td>${arr && arr[k] !== undefined && arr[k] !== null && arr[k] !== '' ? esc(arr[k]) : '<span class="vac">·</span>'}</td>`).join('');
        const emt = d.i.tipo === 'inicial' ? vol?.emt_inicial : vol?.emt;
        const rep = vol?.repetibilidad;
        const ev = (x, lim) => (x === null || x === undefined || x === '' || lim === null || lim === undefined ? '' : (Math.abs(Number(x)) <= Number(lim) ? 'Cumple' : 'No cumple'));
        return `<table class="met">
            <tr><td class="hd" colspan="25">Marca: <b>${v(l.marca)}</b> &nbsp; Modelo: <b>${v(l.modelo)}</b> &nbsp; Serie: <b>${v(l.serie)}</b></td></tr>
            <tr><td class="hd" colspan="25">I.D. Posición: <b>${v(l.lado)}</b> &nbsp; Producto: <b>${v(l.combustible)}</b> &nbsp; Medida Volumetrica: <b>${v(mv)}</b> &nbsp; Distintivo: <b>${v(l.distintivo)}</b> &nbsp; Flexograma: <b>${v(l.flexograma)}</b> &nbsp; Precinto: <b>${v(l.precinto)}</b></td></tr>
            <tr><th rowspan="2">Gastos</th><th colspan="3">Lc Div 10ml</th><th colspan="3">E. Rep. ml</th><th colspan="3">T(Min)</th><th colspan="3">T(ºC)</th><th colspan="6">(Dispensario)(mL)</th><th colspan="3">Vcmv</th><th colspan="3">qv. L/Min</th></tr>
            <tr>${['Lc 1', 'Lc 2', 'Lc 3', '1', '2', '3', '1', '2', '3', '1', '2', '3', '1', 'Dif', '2', 'Dif', '3', 'Dif', '1', '2', '3', '1', '2', '3'].map((h) => `<th>${h}</th>`).join('')}</tr>
            ${G.map(([k, n]) => { const g = p[k] || {}; return `<tr><td style="text-align:left">${n}</td>${celdas(g.lc, 3)}${celdas(g.rep, 3)}${celdas(g.t, 3)}${celdas(g.temp, 3)}${celdas(g.disp, 6)}${celdas(g.vcmv, 3)}${celdas(g.qv, 3)}</tr>`; }).join('')}
            <tr><td colspan="25" style="text-align:left">Error en prueba de repetibilidad: <b>${v(p.rep_resultado ?? rep)}</b> ${ev(p.rep_resultado, rep) || ''} &nbsp;&nbsp; Errores máximos tolerados +/-: <b>${v(emt)}</b> ${p.e_max !== undefined ? ev(p.e_max, emt) : ''}</td></tr>
        </table>`;
    }

    function dictamen(d) {
        const { i, est, lados, equipo } = d;
        const avisos = [];
        if (!lados.length) avisos.push('La verificación no tiene lados capturados.');
        if (!equipo) avisos.push('El verificador no tiene equipo patrón activo en SCFI → Equipos.');
        if (!lados.some((l) => l.pruebas)) avisos.push('Aún no hay captura de corridas (Lc, tiempos, temperaturas): las tablas de pruebas salen en blanco.');
        if (!i.hora_inicio || !i.hora_fin) avisos.push('Faltan hora de inicio o de término.');
        if (!visitado(d)) avisos.push('La estación no tiene encargado capturado (nombre del visitado).');
        const nom = nombreInspector(d), vis = visitado(d);
        const vol = instPatron(equipo, 'volumetrico');
        const mv = vol ? (vol.id_interna || vol.serie || '') : '';
        const paginas = [];

        // Hoja 1: portada + resultado (hasta 14 lados; el resto continúa en hojas siguientes)
        const fila = (l) => `<tr><td>${v(l.marca)}</td><td>${v(l.modelo)}</td><td>${v(l.serie)}</td><td>${v(l.lado)}</td><td>${v(l.combustible)}</td><td>${v(l.flexograma)}</td><td>${v(l.distintivo)}</td><td>${v(l.precinto)}</td><td>${l.resultado === 'rechaza' ? 'No cumple' : 'Cumple'}</td><td>${v(mv)}</td></tr>`;
        const thRes = `<tr class="thg">${['MARCA', 'MODELO', 'NO DE SERIE', 'I.D. POSICION DE CARGA', 'PRODUCTO', 'No DE HOLOGRAMA PROFECO', 'No DE DISTINTIVO EMPRESARIAL', 'ID PRECINTO', 'Dictaminación NOM', 'No. de Serie Medida Volumetrica'].map((h) => `<th>${h}</th>`).join('')}</tr>`;
        const primeros = lados.slice(0, 14), resto = lados.slice(14);
        paginas.push(`
            ${logos()}
            <p class="gris" style="margin:4px 0 0;font-size:11px">El presente Dictamen de Inspección no se reproducirá sin omitir nada, sin la aprobación de la Unidad de Inspección y el Cliente.</p>
            <p style="margin:0;font-size:11px;text-align:justify">En ${v(lugar(est))} siendo las ${hhmm(i.hora_inicio) || '____'} horas, del día ${fecha(i.fecha_inspeccion)} el suscrito, inspector de la Unidad de Inspección ${UI}, se presentó en la estación de servicio de razón social: ${v(d.cli.razon_social || i.razon_social)} con numero de estación: ${v(permiso(d))} y domicilio ubicado en: ${v(domicilio(est))} con el objeto de llevar a cabo la inspección volumétrica de sus instrumentos de medición de acuerdo a lo estipulado en la Ley de la Infraestructura de la Calidad, publicada en el Diario Oficial de la Federación con fecha 1° de julio del 2020, con el objeto de llevar a cabo la inspección volumétrica de sus instrumentos de medición de acuerdo a lo estipulado en la norma oficial mexicana <b>NOM-005-SCFI-2017,</b> <span style="font-size:9px">"Instrumentos de medición-Sistema para medición y despacho de gasolina y otros combustibles líquidos con un gasto máximo de 250 L/min-Especificaciones, métodos de prueba y de inspección" y la Lista de instrumentos de medición cuya inspección inicial, periódica o extraordinaria es obligatoria, así como las normas para efectuarla.</span></p>
            <p style="font-size:11px">A continuación se procedió a inspeccionar los instrumentos de medición del establecimiento, previa solicitud de servicio obteniendo los resultados asentados en el dictamen No: ${v(i.folio)}</p>
            <p class="c bold" style="margin:6px 0 0;font-size:11px">Cumplimiento de Norma y Documentos de Referencia:</p>
            <p class="bold" style="margin:0;font-size:11px">NOM-005-SCFI-2017, Instrumentos de medición-Sistema para medición y despacho de gasolina y otros combustibles líquidos con un gasto máximo de 250 L/min-Especificaciones, métodos de prueba y de inspección. Para la inspección se emplea el Procedimiento de inspección de sistemas para medición y despacho de gasolina y otros combustibles líquidos. Lista de Instrumentos cuya inspección inicial, periódica y/o extraordinaria son obligatorias así como las normas aplicables para efectuarla.<br>RESULTADO DE LA INSPECCIÓN<br>Tipo de inspección: <span style="font-weight:normal">${v(TIPOS[i.tipo] || i.tipo)}</span></p>
            <table style="margin-top:10px">${thRes}<tbody class="tdg">${primeros.map(fila).join('')}</tbody></table>`);
        for (let k = 0; k < resto.length; k += 30) paginas.push(`<p class="bold" style="margin:8px 0 4px">RESULTADO DE LA INSPECCIÓN (continuación)</p><table>${thRes}<tbody class="tdg">${resto.slice(k, k + 30).map(fila).join('')}</tbody></table>`);

        // Hoja: personal técnico y firmas
        paginas.push(`
            <p style="margin-top:14px"><b>Datos del personal técnico inspector</b></p>
            <p>Nombre: ${v(nom)}<br>No de credencial: ${v(d.inspector?.credencial || d.inspector?.no_credencial)}<br>No de Solicitud de Servicio: ${v(i.folio)}</p>
            <p><b>Declaración del visitado:</b></p><div style="border-bottom:1px solid #999;height:40px"></div>
            <p style="text-align:justify">No habiendo más que agregar, se da por terminada esta diligencia a las ${hhmm(i.hora_fin) || '____'} horas del ${fecha(i.fecha_termino || i.fecha_inspeccion)} Levantándose el presente dictamen de verificación en términos de ley, la que después de leída fue firmada al calce y a al margen por todos los que en ella intervinieron entregándose original de la misma al visitado.</p>
            <p>Latitud: ${v(est.lat)}<br>Longitud: ${v(est.lng)}</p>
            <table style="margin-top:40px"><tr><td style="width:50%"><b>${UI}</b><br>Nombre: ${v(nom)}<br><br><br>Firma: ______________________</td><td><b>Estación de Servicio:</b>${v(noEstacion(d))}<br>Nombre: ${v(vis)}<br><br><br>Firma: ______________________</td></tr></table>`);

        // Hojas de pruebas metrológicas (3 lados por hoja)
        for (let k = 0; k < lados.length; k += 3) paginas.push(`<div style="margin-top:8px">${lados.slice(k, k + 3).map((l) => bloqueMetrologico(d, l)).join('')}</div>`);

        // Hoja: inspección visual por dispensario
        const disp = {};
        lados.forEach((l) => { const k = `${l.marca}|${l.modelo}|${l.serie}`; (disp[k] = disp[k] || { ...l, todos: [] }).todos.push(l); });
        const marca = (ok) => [ok ? 'X' : '', ok ? '' : 'X'];
        const faltaDisp = [];
        const visual = Object.values(disp).map((x) => {
            const ok = x.todos.every((l) => l.resultado !== 'rechaza');
            const [si, no] = marca(ok);
            const pts = ['Condiciones que generen desperfectos (9.2)', 'Preparación del Sistema y corrida de ambientación (7.2.4) y (7.2.4.2)', 'Nivelación de la medida volumétrica 7.2.4.1', 'Leyendas información importante para el consumidor. (9.2)', 'Tipo de producto a despachar en forma clara y precisa. (9.2)', 'Dispositivos computador debe marcar ceros (9.2.1)', 'Caratula indicadora (9.2.2 y 5.3.2.3.)', 'Mecanismo de ajuste (9.2.3 y 5.3.3)', 'Mangueras de descarga(9.2.4.1)'];
            const gmin = x.gasto_min ?? '', gmax = x.gasto_max ?? '';
            if (!x.aprobacion_dgn || gmin === '' || gmax === '') faltaDisp.push(x.serie || 'sin serie');
            return `<div class="met" style="margin-top:6px"><p style="margin:2px 0"><b>Dispensario</b><br>Marca: ${v(x.marca)} &nbsp; Modelo: ${v(x.modelo)} &nbsp; No.: ${v(x.serie)}</p>
                <table style="width:100%"><tr><td style="width:48%;vertical-align:top;border:0;padding:0">
                    <table><tr><th>VERFICACIÓN VISUAL<br>Puntos a Inspeccionar de la NOM-005-SCFI-2017</th><th>Cumple</th><th>No cumple</th></tr>
                    ${pts.map((t) => `<tr><td style="text-align:left">${t}</td><td>${si}</td><td>${no}</td></tr>`).join('')}</table>
                </td><td style="vertical-align:top;border:0;padding:0 0 0 8px">
                    <table><tr><th colspan="5">APROBACIÓN DE MODELO O PROTOTIPO (ALCANCE DE MEDICIÓN)</th></tr>
                    <tr><td colspan="5" style="text-align:left">No de Aprobación DGN: ${v(x.aprobacion_dgn) || '<span class="vac">________________</span>'}</td></tr>
                    <tr><th>Puntos a Inspeccionar</th><th>Min (L/min)</th><th>Max (L/min)</th><th>1/10 del Max</th><th>Cumple</th></tr>
                    <tr><td>NOM-005-SCFI-2017</td><td>${v(gmin)}</td><td>${v(gmax)}</td><td>${gmax !== '' ? Number(gmax) / 10 : ''}</td><td>${gmin !== '' && gmax !== '' ? (Number(gmin) <= Number(gmax) / 10 ? 'X' : 'No cumple') : ''}</td></tr>
                    <tr><td colspan="5" style="text-align:left;font-size:7px">El gasto mínimo de un sistema para medición declarado por el fabricante no debe ser menor a la décima parte del gasto máximo.</td></tr></table>
                </td></tr></table></div>`;
        });
        for (let k = 0; k < visual.length; k += 2) paginas.push(`${k === 0 ? '<p class="c bold" style="margin:8px 0 2px">INSPECCIÓN VISUAL CONFORME AL PUNTO 9.2 Y 9.3.2 DE LA NOM-005-SCFI-2017</p>' : ''}${visual.slice(k, k + 2).join('')}`);
        if (faltaDisp.length) avisos.push(`Dispensario(s) sin aprobación DGN o gastos mín/máx (Catálogos → Clientes → Estaciones → Dispensarios): ${faltaDisp.join(', ')}.`);
        if (!visual.length) paginas.push('<p class="c bold">INSPECCIÓN VISUAL CONFORME AL PUNTO 9.2 Y 9.3.2 DE LA NOM-005-SCFI-2017</p><p class="c vac">Sin dispensarios capturados.</p>');

        // Hoja final: observaciones, equipo patrón, firmas y fórmulas
        const I = (k) => instPatron(equipo, k) || {};
        const filaEq = (nombre, x, conCal = true) => `<tr><td style="text-align:left">${nombre}</td><td>${v(x.id_interna)}</td><td>${v(x.marca)}</td><td>${v(x.modelo)}</td><td>${v(x.serie, conCal ? 'S/N' : '')}</td><td>${conCal ? v(x.laboratorio) : ''}</td><td>${conCal ? v(x.fecha) : ''}</td><td>${conCal ? v(x.informe || x.certificado) : ''}</td></tr>`;
        const V = I('volumetrico');
        paginas.push(`
            <table class="b" style="margin-top:10px"><tr><td style="width:14%" class="bold">OBSERVACIONES:</td><td style="height:50px;vertical-align:top">${v(i.observaciones)}</td></tr></table>
            <p class="bold" style="margin:10px 0 2px">Equipos patrón utilizado para la inspección:</p>
            <table class="met"><tr><th></th><th>I.D. Instrumento Patrón</th><th>Marca</th><th>Modelo</th><th>No. de Serie</th><th>Calibrado Por</th><th>Fecha de Calibración</th><th>Informe No.</th></tr>
                ${filaEq('Medida Volumétrica:', V)}${filaEq('Termómetro:', I('termometro'))}${filaEq('Cronometro:', I('crono'))}
                <tr><td colspan="8" style="text-align:left">Volumen Convencional (ml): <b>${v(V.valor_certificado)}</b> &nbsp;&nbsp; Valor de Kc: <b>${v(V.kc)}</b> &nbsp;&nbsp; Valor de α (°C-1 ): <b>${ALFA}</b></td></tr>
                ${filaEq('Mesa Niveladora:', I('mesa'), false)}${filaEq('Embudo:', I('embudo'), false)}</table>
            <p>Mantenimiento del Equipo &nbsp; Si <b>X</b> &nbsp; No ___</p>
            <table style="margin-top:36px"><tr>
                <td style="width:28%"><div class="firma">${v(nom)}<br>FIRMA INSPECTOR</div></td><td style="width:4%"></td>
                <td style="width:28%"><div class="firma">${v(vis)}<br>NOMBRE Y FIRMA DEL VISITADO</div></td><td style="width:4%"></td>
                <td><div class="firma">${fecha(i.fecha_inspeccion)} ${hora12(i.hora_inicio)}<br>Hora de Inicio</div></td><td style="width:2%"></td>
                <td><div class="firma">${fecha(i.fecha_termino || i.fecha_inspeccion)} ${hora12(i.hora_fin)}<br>Hora de Termino</div></td></tr></table>
            <p style="font-size:7.8px;margin-top:20px;text-align:justify"><b>Observaciones</b><br>Fórmula para el volumen de la medida volumétrica corregido a la temperatura de trabajo Vcmv = (V20+Lc*Kc)Cts. Fórmula para el coeficiente por expansión térmica Cts = 1+α(Tmv-20 oC), α= 0,0000477°-1 para el acero inoxidable. El Error Máximo Tolerado en Inspección Inicial (EMT) es de EMT ≤ 10 (mL) + 2 (mL/L)·Vn (L), Para Inspección Periódica Y Extraordinaria es de EMT ≤ 20 (mL) + 4 (mL/L) · Vn (L), Error Tolerado De Ajuste A Cero 40% del ETM en una inspección periódica y extraordinaria . El Error de Repetibilidad es la diferencian máxima entre los errores de indicación obtenidos en mediciones efectuadas en un mismo gasto. R=Emax-Emin. La tolerancia del Error De Repetibilidad Tolerado = R≤20(ml)+2(ml/L)*Vn(L).</p>`);

        const total = paginas.length;
        const cuerpo = paginas.map((c, n) => `<div class="page">${encabezado(d, n + 1, total)}${c}${pieDict()}</div>`).join('');
        return documento(`Dictamen ${i.folio}`, cuerpo, avisos, `Dictamen_${i.folio}`);
    }

    // ---------------------------------------------------------------
    async function abrir(tipo, id, ventana = null) {
        // La pestaña se abre de inmediato en el clic (evita el bloqueo de ventanas emergentes) y luego se llena.
        const w = ventana || window.open('', '_blank');
        if (!w) { App.toast('El navegador bloqueó la ventana. Permite ventanas emergentes para SUDI.', 'error'); return; }
        w.document.write('<p style="font-family:sans-serif;padding:20px">Generando documento...</p>');
        try {
            const DB = await App.db();
            const d = await datos(DB, id);
            const html = tipo === 'solicitud' ? solicitud(d) : dictamen(d);
            w.document.open(); w.document.write(html); w.document.close();
        } catch (err) {
            w.document.open(); w.document.write(`<p style="font-family:sans-serif;color:#b00;padding:20px">No se pudo generar: ${esc(err.message)}</p>`); w.document.close();
        }
    }

    window.SUDIFormatos = { abrir };
})();
